/*
 * A030747  The first list after the following procedure: starting with a list
 *          [4] and an empty list, repeatedly add the distinct values already
 *          in both lists in ascending order to the second list and add the
 *          corresponding frequencies of those values to the first list.
 * https://oeis.org/A030747
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   generated by the iterative procedure described in the OEIS
 *            entry. The sequence a(1) = 4, a(2) = 1, a(3) = 1, a(4) = 2, ...
 *            (see A030747)
 * Range:     u8 n <= 81, u16 n <= 81, u32 n <= 81, u64 n <= 81, u128 n <= 81,
 *            big any n
 * Helpers:   seq_equal, seq_to_str
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <stddef.h>

#include "../utils/seq_to_str.h"
#include "../utils/seq_equal.h"

/* --------------------------------------------------------------------- */
/* Hash table for counts (total frequency across both lists) and presence
   of a value in the first list.                                       */
typedef struct {
    seq_t key;     /* the value */
    size_t val;    /* total frequency across both lists */
    bool present;  /* true if the value occurs in the first list */
    bool used;     /* true if entry is occupied */
} HashEntry;

static HashEntry *hash_tab   = NULL;
static size_t     hash_cap   = 0;
static size_t     hash_used  = 0;

/* Simple FNV‑1a hash over the decimal representation of the key. */
static size_t hash_seq(const seq_t *x)
{
    char buf[8192];
    size_t len = 0;
    seq_to_str(*x, buf, &len);
    uint64_t h = 1469598103934665603ULL;
    for (size_t i = 0; i < len; ++i) {
        h ^= (unsigned char)buf[i];
        h *= 1099511628211ULL;
    }
    return (size_t)h;
}

static void hash_rehash(void)
{
    size_t old_cap = hash_cap;
    HashEntry *old_tab = hash_tab;

    hash_cap <<= 1;
    hash_tab = (HashEntry*)calloc(hash_cap, sizeof(HashEntry));
    hash_used = 0;

    for (size_t i = 0; i < old_cap; ++i) {
        if (!old_tab[i].used) continue;
        size_t idx = hash_seq(&old_tab[i].key) % hash_cap;
        while (hash_tab[idx].used) idx = (idx + 1) % hash_cap;
        hash_tab[idx] = old_tab[i];
        hash_used++;
    }
    free(old_tab);
}

static void inc_count(const seq_t key, size_t delta)
{
    if (!hash_tab) {
        hash_cap = 128;
        hash_tab = (HashEntry*)calloc(hash_cap, sizeof(HashEntry));
        hash_used = 0;
    }
    if (hash_used * 2 >= hash_cap) hash_rehash();

    size_t idx = hash_seq(&key) % hash_cap;
    while (hash_tab[idx].used && !seq_equal(&hash_tab[idx].key, &key))
        idx = (idx + 1) % hash_cap;

    if (!hash_tab[idx].used) {
        hash_tab[idx].used    = true;
        hash_tab[idx].key     = key;
        hash_tab[idx].val     = delta;
        hash_tab[idx].present = false;
        hash_used++;
    } else {
        hash_tab[idx].val += delta;
    }
}

static size_t get_count(const seq_t key)
{
    if (!hash_tab) return 0;
    size_t idx = hash_seq(&key) % hash_cap;
    while (hash_tab[idx].used && !seq_equal(&hash_tab[idx].key, &key))
        idx = (idx + 1) % hash_cap;
    if (!hash_tab[idx].used) return 0;
    return hash_tab[idx].val;
}

static bool present_lookup(const seq_t key)
{
    if (!hash_tab) return false;
    size_t idx = hash_seq(&key) % hash_cap;
    while (hash_tab[idx].used && !seq_equal(&hash_tab[idx].key, &key))
        idx = (idx + 1) % hash_cap;
    return hash_tab[idx].used && hash_tab[idx].present;
}

static void present_set_true(const seq_t key)
{
    if (!hash_tab) {
        hash_cap = 128;
        hash_tab = (HashEntry*)calloc(hash_cap, sizeof(HashEntry));
        hash_used = 0;
    }
    if (hash_used * 2 >= hash_cap) hash_rehash();

    size_t idx = hash_seq(&key) % hash_cap;
    while (hash_tab[idx].used && !seq_equal(&hash_tab[idx].key, &key))
        idx = (idx + 1) % hash_cap;

    if (!hash_tab[idx].used) {
        hash_tab[idx].used    = true;
        hash_tab[idx].key     = key;
        hash_tab[idx].val     = 0;
        hash_tab[idx].present = true;
        hash_used++;
    } else {
        hash_tab[idx].present = true;
    }
}

/* --------------------------------------------------------------------- */
/* Dynamic array for the first list (the sequence). */
static seq_t *first = NULL;
static size_t first_len = 0;
static size_t first_cap = 0;

static void grow_first(size_t need)
{
    if (first_cap >= need) return;
    size_t new_cap = first_cap ? first_cap * 2 : 64;
    if (new_cap < need) new_cap = need;
    first = (seq_t*)realloc(first, new_cap * sizeof(seq_t));
    first_cap = new_cap;
}

/* --------------------------------------------------------------------- */
/* Min‑heap of seq_t values (the distinct values present in the first list). */
typedef struct {
    seq_t *data;
    size_t size;
    size_t cap;
} MinHeap;

static MinHeap heap = {NULL, 0, 0};

static void heap_grow(void)
{
    size_t new_cap = heap.cap ? heap.cap * 2 : 64;
    heap.data = (seq_t*)realloc(heap.data, new_cap * sizeof(seq_t));
    heap.cap = new_cap;
}

static void heap_push(seq_t v)
{
    if (heap.size == heap.cap) heap_grow();
    heap.data[heap.size] = v;
    size_t i = heap.size++;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap.data[p] <= heap.data[i]) break;
        seq_t tmp = heap.data[p];
        heap.data[p] = heap.data[i];
        heap.data[i] = tmp;
        i = p;
    }
}

static seq_t heap_pop(void)
{
    seq_t v = heap.data[0];
    heap.size--;
    heap.data[0] = heap.data[heap.size];
    size_t i = 0;
    while (true) {
        size_t l = (i << 1) + 1;
        if (l >= heap.size) break;
        size_t r = l + 1;
        size_t s = (r < heap.size && heap.data[r] < heap.data[l]) ? r : l;
        if (heap.data[i] <= heap.data[s]) break;
        seq_t tmp = heap.data[i];
        heap.data[i] = heap.data[s];
        heap.data[s] = tmp;
        i = s;
    }
    return v;
}

static size_t heap_size(void) { return heap.size; }

/* --------------------------------------------------------------------- */
/* Main sequence function. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined for index < 1 */

    /* one time initialization */
    static bool initialized = false;
    if (!initialized) {
        initialized = true;
        /* first list */
        grow_first(1);
        first[0] = (seq_t)4;
        first_len = 1;

        /* counts */
        inc_count((seq_t)4, 1);          /* 4 appears in first list */
        /* presence */
        present_set_true((seq_t)4);
        /* heap of distinct values */
        heap_push((seq_t)4);
    }

    /* generate further terms until we have at least n elements in first */
    while (first_len < (size_t)n) {
        size_t k = heap_size();
        if (k == 0) break; /* safety, should not happen */

        seq_t *vals = (seq_t*)malloc(k * sizeof(seq_t));
        seq_t *freqs = (seq_t*)malloc(k * sizeof(seq_t));

        /* pop all distinct values, compute their current frequencies */
        for (size_t i = 0; i < k; ++i) {
            vals[i] = heap_pop();
            freqs[i] = get_count(vals[i]);   /* frequency before this step */
        }

        /* append frequencies to first list, update counts and presence */
        for (size_t i = 0; i < k; ++i) {
            grow_first(first_len + 1);
            first[first_len++] = freqs[i];
            inc_count(freqs[i], 1);          /* new element in first list */

            if (!present_lookup(freqs[i])) {
                present_set_true(freqs[i]);
                heap_push(freqs[i]);         /* new distinct value appears in first list */
            }
        }

        /* add values to second list (only counts change) */
        for (size_t i = 0; i < k; ++i) {
            inc_count(vals[i], 1);           /* second list gets one more copy */
        }

        /* re‑insert the original distinct values back into the heap */
        for (size_t i = 0; i < k; ++i) {
            heap_push(vals[i]);
        }

        free(vals);
        free(freqs);
    }

    return first[n - 1];
}
